  String text(String source) {
    final language = locale.languageCode;
    String? v;
    v = _translations[language]?[source];
    if (v != null) return v;
    v = _common[language]?[source];
    if (v != null) return v;
    v = _system[language]?[source];
    if (v != null) return v;
    v = _screens[language]?[source];
    if (v != null) return v;
    v = _remaining[language]?[source];
    if (v != null) return v;
    v = _screenStrings[language]?[source];
    if (v != null) return v;
    v = _screenStrings2[language]?[source];
    if (v != null) return v;
    v = _aboutStrings[language]?[source];
    if (v != null) return v;
    v = _aboutStrings2[language]?[source];
    if (v != null) return v;
    v = _extra[language]?[source];
    if (v != null) return v;
    // Полная цепочка fallback: ru → uk → kk → be → kk → en.
    for (final fb in const ['ru', 'uk', 'kk', 'be']) {
      if (fb == language) continue;
      v = _translations[fb]?[source];
      if (v != null) return v;
      v = _common[fb]?[source];
      if (v != null) return v;
      v = _system[fb]?[source];
      if (v != null) return v;
      v = _screens[fb]?[source];
      if (v != null) return v;
      v = _remaining[fb]?[source];
      if (v != null) return v;
      v = _screenStrings[fb]?[source];
      if (v != null) return v;
      v = _screenStrings2[fb]?[source];
      if (v != null) return v;
      v = _aboutStrings[fb]?[source];
      if (v != null) return v;
      v = _aboutStrings2[fb]?[source];
      if (v != null) return v;
      v = _extra[fb]?[source];
      if (v != null) return v;
    }
    return source;
  }

  String _text(String key) {
    final language = locale.languageCode;
    return _translations[language]?[key] ?? _translations['ru']![key] ?? key;
  }

